#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [-1.239499999999838e-05, -0.338460475, 2.9199999999895976e-06], 'basis': [[-0.26149243056749466, 0.018184482745292288, 0.9650342135609443], [0.0, 0.9998225112415295, -0.018840011005348888], [-0.9652055266915456, -0.0049265202697070295, -0.2614460186006438]], 'axis': [0.9650342135609443, -0.018840011005348888, -0.2614460186006438], 'zmin': -0.2887661902842668, 'zmax': 0.5007966112271773, 'profiles': [{'outer': [[-0.43149717373030394, -0.16306196919748073], [-0.44128365910637407, -0.1574523393019479], [-0.44352525773340745, -0.15554477013728038], [-0.4447406308497307, -0.1535337430828342], [-0.4441277736439059, -0.1351942595777171], [-0.35770622665471385, 0.08477140135479619], [-0.34207360688980853, 0.1055893570356657], [-0.3223794871457659, 0.12144156281634164], [-0.3039416592102298, 0.1310870386717228], [-0.30100977748552504, 0.130698371402825], [-0.2968761156915646, 0.129363486489136], [-0.29202302499055116, 0.12725943510252385], [-0.275151660911512, 0.11776968374087346], [-0.26257177756093214, 0.09879951407903942], [-0.24763214484825735, 0.09819200437592762], [-0.23910751618592188, 0.08838882015375402], [-0.2338223097706575, 0.07229248185982196], [-0.23160817443604223, 0.058596299651080756], [-0.23399695730203862, 0.052113687374949605], [-0.23956574878588235, 0.0458758875129539], [-0.2442340866353257, 0.043680898402562014], [-0.2527893787467756, 0.042316139064626], [-0.25299924389600487, 0.04018959018999979], [-0.40195844371663375, -0.15320286094018454], [-0.4252632325985338, -0.16273467627094346]], 'holes': []}, {'outer': [[0.10407665558312078, 0.06692698043736897], [0.10542255585445923, 0.09331903369114762], [0.11995699973500971, 0.12187981195141435], [0.13830118580913137, 0.14443730995080858], [0.1470323402806131, 0.15138704959619942], [0.15111084562453717, 0.15400082780072316], [0.1562353010950124, 0.15614987847704329], [0.1615918974267093, 0.15752841676991858], [0.16655954151779653, 0.1579526692992015], [0.17032564051512528, 0.15737402672499415], [0.1860397616736939, 0.14848047687959118], [0.2084382985362008, 0.12809518206911935], [0.21223762900380502, 0.12202526788006704], [0.2227270769058333, 0.117681772156643], [0.22622421557789113, 0.11476816564711916], [0.23157184878405881, 0.10804874667526686], [0.23320927532487176, 0.10090016172343404], [0.2310526473943588, 0.09120595086843167], [0.2271980173723679, 0.08478938120272679], [0.2749421578492104, -0.10936459653959764], [0.2718130696136049, -0.12819317279830011], [0.2701390630064463, -0.13049312648538372], [0.26481369489232914, -0.13474767397617235], [0.26373233142805125, -0.13511338035025877], [0.25026282821523754, -0.13487593321873895], [0.227750003774049, -0.12561397517773806]], 'holes': []}, {'outer': [[0.337383074282659, 0.11306539693963621], [0.34377336283320886, 0.12159098179139859], [0.3458081575727243, 0.12324289167469163], [0.3596921765149316, 0.12364021350568076], [0.3672205956297172, 0.12176241409247968], [0.3709678502947418, 0.11976416696445383], [0.37242946121776294, 0.12290868035697913], [0.38963993875012676, 0.14462189500086622], [0.39943910491625173, 0.15130330362884425], [0.4038199427381207, 0.15376466386637155], [0.40895916502141344, 0.15589949348833756], [0.41410193113663424, 0.1573412677011792], [0.41865903317729647, 0.15796504135192652], [0.42174068426288536, 0.15751369685242825], [0.4382953771633673, 0.148381396038658], [0.45650600280904174, 0.13237356160591596], [0.45968737725725983, 0.12829479806840952], [0.47386455934055316, 0.10670656969424126], [0.5377155859148467, -0.11265781683617503], [0.5359021530494129, -0.13021490079871378], [0.53434053309811, -0.13294439028458957], [0.5332615344701617, -0.13389417590554903], [0.5281722774736686, -0.13741356392102105], [0.5262243165529205, -0.13832106305965666], [0.5144335734911353, -0.13858736114871043], [0.49117479102652306, -0.12910641367918882], [0.35795825549166016, 0.06596609014989105], [0.35798878964947356, 0.06847861755682726], [0.35408794527967286, 0.06762136977054332], [0.35029790136070127, 0.06762492849147347], [0.33738800674408137, 0.0709513213800047], [0.3348560590358896, 0.07242001470003338], [0.33094913369145346, 0.07914532996683883], [0.32982950060673544, 0.08481136696789886], [0.3322989857227257, 0.09770568177704393]], 'holes': []}], 'simplify_tolerance': 0.00019649124335291548, 'sketch_entity_count': 89}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
